{
  "name": "scalable-shopping-cart",
  "version": "1.0.0",
  "description": "Carrito de la compra escalable con arquitectura hexagonal, control de concurrencia optimista, idempotencia, motor de promociones y API REST",
  "type": "module",
  "main": "src/index.ts",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --test tests/*.test.ts",
    "start": "node src/main.ts",
    "demo": "node src/demo.ts"
  },
  "engines": {
    "node": ">=22.18.0"
  }
}

// Minimal ambient declarations for Node.js built-in modules used by this project,
// allowing strict type-checking with zero external devDependencies (@types/node).

declare var process: {
  env: Record<string, string | undefined>;
  exit(code?: number): never;
  on(event: string, listener: (...args: unknown[]) => void): void;
};

declare var console: {
  log(...args: unknown[]): void;
  info(...args: unknown[]): void;
  warn(...args: unknown[]): void;
  error(...args: unknown[]): void;
};

declare function setTimeout(callback: (...args: unknown[]) => void, ms?: number): unknown;
declare function clearTimeout(id: unknown): void;

declare class Buffer extends Uint8Array {
  static concat(list: readonly Uint8Array[]): Buffer;
  static from(input: string, encoding?: string): Buffer;
  override toString(encoding?: string): string;
}

declare class URL {
  pathname: string;
  searchParams: {
    get(name: string): string | null;
  };
  constructor(url: string, base?: string);
}

declare interface FetchResponse {
  status: number;
  ok: boolean;
  headers: {
    get(name: string): string | null;
  };
  json(): Promise<unknown>;
  text(): Promise<string>;
}

declare function fetch(
  url: string,
  init?: {
    method?: string;
    headers?: Record<string, string>;
    body?: string;
  },
): Promise<FetchResponse>;

declare module "node:crypto" {
  export function randomUUID(): string;
  export function createHash(algorithm: string): {
    update(data: string): { digest(encoding: "hex" | "base64"): string };
  };
}

declare module "node:http" {
  export interface IncomingMessage extends AsyncIterable<Buffer> {
    method?: string;
    url?: string;
    headers: Record<string, string | string[] | undefined>;
    destroy(error?: Error): void;
  }

  export interface ServerResponse {
    statusCode: number;
    setHeader(name: string, value: string | number | readonly string[]): void;
    writeHead(statusCode: number, headers?: Record<string, string | number>): this;
    end(chunk?: string | Buffer): void;
  }

  export interface AddressInfo {
    address: string;
    family: string;
    port: number;
  }

  export interface Server {
    listen(port?: number, host?: string, callback?: () => void): this;
    address(): AddressInfo | string | null;
    close(callback?: (err?: Error) => void): this;
  }

  export function createServer(
    listener: (req: IncomingMessage, res: ServerResponse) => void | Promise<void>,
  ): Server;
}

declare module "node:fs/promises" {
  export function readFile(path: string, encoding: "utf-8"): Promise<string>;
  export function writeFile(path: string, data: string, encoding?: "utf-8"): Promise<void>;
  export function rename(oldPath: string, newPath: string): Promise<void>;
  export function mkdir(path: string, options?: { recursive?: boolean }): Promise<string | undefined>;
  export function rm(path: string, options?: { recursive?: boolean; force?: boolean }): Promise<void>;
  export function mkdtemp(prefix: string): Promise<string>;
}

declare module "node:path" {
  export function dirname(path: string): string;
  export function join(...paths: string[]): string;
}

declare module "node:os" {
  export function tmpdir(): string;
}

declare module "node:test" {
  export function describe(name: string, fn: () => void | Promise<void>): void;
  export function it(name: string, fn: () => void | Promise<void>): void;
  export function beforeEach(fn: () => void | Promise<void>): void;
  export function afterEach(fn: () => void | Promise<void>): void;
}

declare module "node:assert/strict" {
  export function equal<T>(actual: unknown, expected: T, message?: string): asserts actual is T;
  export function notEqual(actual: unknown, expected: unknown, message?: string): void;
  export function deepEqual(actual: unknown, expected: unknown, message?: string): void;
  export function ok(value: unknown, message?: string): asserts value;
  export function match(str: string, regexp: RegExp, message?: string): void;
  export function throws(fn: () => unknown, error?: RegExp | Function | Record<string, unknown>, message?: string): void;
  export function rejects(
    asyncFn: (() => Promise<unknown>) | Promise<unknown>,
    error?: RegExp | Function | Record<string, unknown>,
    message?: string,
  ): Promise<void>;
}

export type DomainErrorCode =
  | "VALIDATION_ERROR"
  | "CART_NOT_FOUND"
  | "PRODUCT_NOT_FOUND"
  | "CURRENCY_MISMATCH"
  | "CONCURRENCY_CONFLICT"
  | "INSUFFICIENT_STOCK"
  | "CART_LIMIT_EXCEEDED"
  | "INVALID_CART_STATE"
  | "INVALID_COUPON"
  | "LOCK_TIMEOUT"
  | "IDEMPOTENCY_CONFLICT";

export class DomainError extends Error {
  readonly code: DomainErrorCode;
  readonly details?: Record<string, unknown>;

  constructor(code: DomainErrorCode, message: string, details?: Record<string, unknown>) {
    super(message);
    this.name = new.target.name;
    this.code = code;
    this.details = details;
  }
}

export class ValidationError extends DomainError {
  constructor(message: string, details?: Record<string, unknown>) {
    super("VALIDATION_ERROR", message, details);
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super("CART_NOT_FOUND", `Cart "${cartId}" was not found`, { cartId });
  }
}

export class ProductNotFoundError extends DomainError {
  constructor(sku: string) {
    super("PRODUCT_NOT_FOUND", `Product SKU "${sku}" was not found`, { sku });
  }
}

export class CurrencyMismatchError extends DomainError {
  constructor(expected: string, actual: string) {
    super(
      "CURRENCY_MISMATCH",
      `Currency mismatch: expected "${expected}", got "${actual}"`,
      { expected, actual },
    );
  }
}

export class ConcurrencyConflictError extends DomainError {
  constructor(cartId: string, expectedVersion: number, actualVersion: number) {
    super(
      "CONCURRENCY_CONFLICT",
      `Optimistic lock failed for cart "${cartId}": expected version ${expectedVersion}, found ${actualVersion}`,
      { cartId, expectedVersion, actualVersion },
    );
  }
}

export class InsufficientStockError extends DomainError {
  constructor(sku: string, requested: number, available: number) {
    super(
      "INSUFFICIENT_STOCK",
      `Insufficient stock for SKU "${sku}": requested ${requested}, available ${available}`,
      { sku, requested, available },
    );
  }
}

export class CartLimitExceededError extends DomainError {
  constructor(message: string, details?: Record<string, unknown>) {
    super("CART_LIMIT_EXCEEDED", message, details);
  }
}

export class InvalidCartStateError extends DomainError {
  constructor(cartId: string, currentState: string, action: string) {
    super(
      "INVALID_CART_STATE",
      `Cannot ${action} cart "${cartId}" while in state "${currentState}"`,
      { cartId, currentState, action },
    );
  }
}

export class InvalidCouponError extends DomainError {
  constructor(code: string, reason: string) {
    super("INVALID_COUPON", `Coupon "${code}" cannot be applied: ${reason}`, { code, reason });
  }
}

export class LockTimeoutError extends DomainError {
  constructor(key: string, timeoutMs: number) {
    super("LOCK_TIMEOUT", `Timed out acquiring lock for "${key}" after ${timeoutMs}ms`, {
      key,
      timeoutMs,
    });
  }
}

export class IdempotencyConflictError extends DomainError {
  constructor(key: string, reason: string) {
    super("IDEMPOTENCY_CONFLICT", `Idempotency key "${key}" conflict: ${reason}`, { key, reason });
  }
}

import { CurrencyMismatchError, ValidationError } from "./errors.ts";

export interface MoneyJSON {
  amountMinor: number;
  currency: string;
  formatted: string;
}

const CURRENCY_REGEX = /^[A-Z]{3}$/;

/**
 * Immutable Value Object representing money in minor integer units (e.g. cents)
 * to eliminate floating-point precision drift across distributed pricing calculations.
 */
export class Money {
  readonly amountMinor: number;
  readonly currency: string;

  private constructor(amountMinor: number, currency: string) {
    if (!Number.isSafeInteger(amountMinor)) {
      throw new ValidationError(`Money amountMinor must be a safe integer, received: ${amountMinor}`);
    }
    const normalized = currency.trim().toUpperCase();
    if (!CURRENCY_REGEX.test(normalized)) {
      throw new ValidationError(`Invalid ISO 4217 currency code: "${currency}"`);
    }
    this.amountMinor = amountMinor;
    this.currency = normalized;
  }

  static ofMinor(amountMinor: number, currency: string): Money {
    return new Money(amountMinor, currency);
  }

  static ofMajor(amountMajor: number, currency: string): Money {
    if (!Number.isFinite(amountMajor)) {
      throw new ValidationError(`Money amountMajor must be finite, received: ${amountMajor}`);
    }
    return new Money(Math.round(amountMajor * 100), currency);
  }

  static zero(currency: string): Money {
    return new Money(0, currency);
  }

  private assertSameCurrency(other: Money): void {
    if (this.currency !== other.currency) {
      throw new CurrencyMismatchError(this.currency, other.currency);
    }
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor + other.amountMinor, this.currency);
  }

  subtract(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(this.amountMinor - other.amountMinor, this.currency);
  }

  subtractClampedZero(other: Money): Money {
    this.assertSameCurrency(other);
    return new Money(Math.max(0, this.amountMinor - other.amountMinor), this.currency);
  }

  multiply(factor: number): Money {
    if (!Number.isFinite(factor)) {
      throw new ValidationError(`Multiplication factor must be finite, received: ${factor}`);
    }
    return new Money(Math.round(this.amountMinor * factor), this.currency);
  }

  percentage(percent: number): Money {
    if (!Number.isFinite(percent) || percent < 0) {
      throw new ValidationError(`Percentage must be a non-negative finite number, received: ${percent}`);
    }
    return new Money(Math.round((this.amountMinor * percent) / 100), this.currency);
  }

  min(other: Money): Money {
    this.assertSameCurrency(other);
    return this.amountMinor <= other.amountMinor ? this : other;
  }

  max(other: Money): Money {
    this.assertSameCurrency(other);
    return this.amountMinor >= other.amountMinor ? this : other;
  }

  isNegative(): boolean {
    return this.amountMinor < 0;
  }

  isZero(): boolean {
    return this.amountMinor === 0;
  }

  greaterThanOrEqual(other: Money): boolean {
    this.assertSameCurrency(other);
    return this.amountMinor >= other.amountMinor;
  }

  equals(other: Money): boolean {
    return this.currency === other.currency && this.amountMinor === other.amountMinor;
  }

  format(): string {
    const sign = this.amountMinor < 0 ? "-" : "";
    const abs = Math.abs(this.amountMinor);
    const major = Math.floor(abs / 100);
    const minor = String(abs % 100).padStart(2, "0");
    return `${sign}${major}.${minor} ${this.currency}`;
  }

  toJSON(): MoneyJSON {
    return {
      amountMinor: this.amountMinor,
      currency: this.currency,
      formatted: this.format(),
    };
  }
}

import type { MoneyJSON } from "./money.ts";

export interface DomainEventBase<TType extends string, TPayload> {
  readonly eventId: string;
  readonly type: TType;
  readonly cartId: string;
  readonly cartVersion: number;
  readonly occurredAt: string;
  readonly payload: TPayload;
}

export type CartCreatedEvent = DomainEventBase<
  "CartCreated",
  {
    ownerId: string | null;
    currency: string;
  }
>;

export type CartItemAddedEvent = DomainEventBase<
  "CartItemAdded",
  {
    sku: string;
    quantityAdded: number;
    resultingQuantity: number;
    unitPrice: MoneyJSON;
  }
>;

export type CartItemQuantityUpdatedEvent = DomainEventBase<
  "CartItemQuantityUpdated",
  {
    sku: string;
    previousQuantity: number;
    newQuantity: number;
  }
>;

export type CartItemRemovedEvent = DomainEventBase<
  "CartItemRemoved",
  {
    sku: string;
    removedQuantity: number;
  }
>;

export type CartClearedEvent = DomainEventBase<
  "CartCleared",
  {
    clearedItemCount: number;
  }
>;

export type CartCouponAppliedEvent = DomainEventBase<
  "CartCouponApplied",
  {
    code: string;
  }
>;

export type CartCouponRemovedEvent = DomainEventBase<
  "CartCouponRemoved",
  {
    code: string;
  }
>;

export type CartMergedEvent = DomainEventBase<
  "CartMerged",
  {
    sourceCartId: string;
    mergedSkus: string[];
  }
>;

export type CartCheckedOutEvent = DomainEventBase<
  "CartCheckedOut",
  {
    orderId: string;
    ownerId: string | null;
    reservationId: string;
    grandTotal: MoneyJSON;
    itemCount: number;
  }
>;

export type CartExpiredEvent = DomainEventBase<
  "CartExpired",
  {
    expiredAt: string;
  }
>;

export type CartDomainEvent =
  | CartCreatedEvent
  | CartItemAddedEvent
  | CartItemQuantityUpdatedEvent
  | CartItemRemovedEvent
  | CartClearedEvent
  | CartCouponAppliedEvent
  | CartCouponRemovedEvent
  | CartMergedEvent
  | CartCheckedOutEvent
  | CartExpiredEvent;

import { randomUUID } from "node:crypto";
import {
  CartLimitExceededError,
  CurrencyMismatchError,
  InvalidCartStateError,
  ValidationError,
} from "./errors.ts";
import type { CartDomainEvent } from "./events.ts";
import { Money } from "./money.ts";

export type CartStatus = "ACTIVE" | "CHECKED_OUT" | "EXPIRED" | "MERGED";

export interface CartLimits {
  readonly maxDistinctItems: number;
  readonly maxQuantityPerItem: number;
  readonly maxCoupons: number;
  readonly defaultTtlMs: number;
}

export const DEFAULT_CART_LIMITS: CartLimits = {
  maxDistinctItems: 100,
  maxQuantityPerItem: 99,
  maxCoupons: 5,
  defaultTtlMs: 7 * 24 * 60 * 60 * 1000, // 7 days
};

export interface CartItemSnapshot {
  sku: string;
  name: string;
  category: string;
  unitPriceMinor: number;
  currency: string;
  quantity: number;
  taxExempt?: boolean;
  addedAt: string;
  updatedAt: string;
  metadata?: Record<string, string>;
}

export interface CartSnapshot {
  id: string;
  ownerId: string | null;
  currency: string;
  status: CartStatus;
  version: number;
  items: CartItemSnapshot[];
  coupons: string[];
  shippingRegion: string;
  metadata: Record<string, string>;
  createdAt: string;
  updatedAt: string;
  expiresAt: string;
}

export interface CreateCartInput {
  id?: string;
  ownerId?: string | null;
  currency?: string;
  shippingRegion?: string;
  ttlMs?: number;
  metadata?: Record<string, string>;
  now?: Date;
}

export interface AddCartItemInput {
  sku: string;
  name: string;
  category: string;
  unitPrice: Money;
  quantity: number;
  taxExempt?: boolean;
  metadata?: Record<string, string>;
  now?: Date;
}

/**
 * Cart Aggregate Root.
 * Enforces all domain invariants, optimistic versioning, TTL expiration,
 * resource limits, and emits domain events for downstream consumers.
 */
export class Cart {
  readonly id: string;
  private _ownerId: string | null;
  readonly currency: string;
  private _status: CartStatus;
  private _version: number;
  private readonly _items: Map<string, CartItemSnapshot>;
  private readonly _coupons: Set<string>;
  private _shippingRegion: string;
  private readonly _metadata: Record<string, string>;
  readonly createdAt: Date;
  private _updatedAt: Date;
  private _expiresAt: Date;
  private readonly limits: CartLimits;
  private readonly pendingEvents: CartDomainEvent[] = [];

  private constructor(
    snapshot: CartSnapshot,
    limits: CartLimits = DEFAULT_CART_LIMITS,
  ) {
    this.id = snapshot.id;
    this._ownerId = snapshot.ownerId;
    this.currency = snapshot.currency;
    this._status = snapshot.status;
    this._version = snapshot.version;
    this._items = new Map(snapshot.items.map((item) => [item.sku, { ...item }]));
    this._coupons = new Set(snapshot.coupons);
    this._shippingRegion = snapshot.shippingRegion;
    this._metadata = { ...snapshot.metadata };
    this.createdAt = new Date(snapshot.createdAt);
    this._updatedAt = new Date(snapshot.updatedAt);
    this._expiresAt = new Date(snapshot.expiresAt);
    this.limits = limits;
  }

  static create(input: CreateCartInput = {}, limits: CartLimits = DEFAULT_CART_LIMITS): Cart {
    const now = input.now ?? new Date();
    const currency = (input.currency ?? "EUR").trim().toUpperCase();
    // Validate currency via Money
    Money.zero(currency);

    const ttlMs = input.ttlMs ?? limits.defaultTtlMs;
    if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
      throw new ValidationError(`ttlMs must be a positive number, received: ${ttlMs}`);
    }

    const id = input.id?.trim() || `cart_${randomUUID()}`;
    const ownerId = input.ownerId ?? null;
    const expiresAt = new Date(now.getTime() + ttlMs);

    const cart = new Cart(
      {
        id,
        ownerId,
        currency,
        status: "ACTIVE",
        version: 1,
        items: [],
        coupons: [],
        shippingRegion: (input.shippingRegion ?? "ES").trim().toUpperCase(),
        metadata: input.metadata ? { ...input.metadata } : {},
        createdAt: now.toISOString(),
        updatedAt: now.toISOString(),
        expiresAt: expiresAt.toISOString(),
      },
      limits,
    );

    cart.recordEvent({
      eventId: randomUUID(),
      type: "CartCreated",
      cartId: cart.id,
      cartVersion: cart._version,
      occurredAt: now.toISOString(),
      payload: { ownerId, currency },
    });

    return cart;
  }

  static fromSnapshot(snapshot: CartSnapshot, limits: CartLimits = DEFAULT_CART_LIMITS): Cart {
    return new Cart(snapshot, limits);
  }

  get ownerId(): string | null {
    return this._ownerId;
  }

  get status(): CartStatus {
    return this._status;
  }

  get version(): number {
    return this._version;
  }

  get shippingRegion(): string {
    return this._shippingRegion;
  }

  get updatedAt(): Date {
    return new Date(this._updatedAt.getTime());
  }

  get expiresAt(): Date {
    return new Date(this._expiresAt.getTime());
  }

  get items(): readonly CartItemSnapshot[] {
    return Array.from(this._items.values(), (item) => ({
      ...item,
      metadata: item.metadata ? { ...item.metadata } : undefined,
    }));
  }

  get coupons(): readonly string[] {
    return Array.from(this._coupons.values());
  }

  get totalItemUnits(): number {
    let total = 0;
    for (const item of this._items.values()) {
      total += item.quantity;
    }
    return total;
  }

  get distinctItemCount(): number {
    return this._items.size;
  }

  getItem(sku: string): CartItemSnapshot | undefined {
    const item = this._items.get(sku);
    return item ? { ...item, metadata: item.metadata ? { ...item.metadata } : undefined } : undefined;
  }

  isExpired(now: Date = new Date()): boolean {
    return this._status === "EXPIRED" || now.getTime() >= this._expiresAt.getTime();
  }

  addItem(input: AddCartItemInput): void {
    const now = input.now ?? new Date();
    this.assertActive("add item to", now);

    const sku = input.sku.trim();
    if (!sku) {
      throw new ValidationError("SKU must be a non-empty string");
    }
    if (!Number.isInteger(input.quantity) || input.quantity <= 0) {
      throw new ValidationError(`Quantity to add must be a positive integer, received: ${input.quantity}`);
    }
    if (input.unitPrice.currency !== this.currency) {
      throw new CurrencyMismatchError(this.currency, input.unitPrice.currency);
    }
    if (input.unitPrice.isNegative()) {
      throw new ValidationError("Item unit price cannot be negative");
    }

    const existing = this._items.get(sku);
    if (!existing && this._items.size >= this.limits.maxDistinctItems) {
      throw new CartLimitExceededError(
        `Cart cannot contain more than ${this.limits.maxDistinctItems} distinct SKUs`,
        { maxDistinctItems: this.limits.maxDistinctItems },
      );
    }

    const nextQuantity = (existing?.quantity ?? 0) + input.quantity;
    if (nextQuantity > this.limits.maxQuantityPerItem) {
      throw new CartLimitExceededError(
        `Quantity for SKU "${sku}" cannot exceed ${this.limits.maxQuantityPerItem}`,
        { sku, maxQuantityPerItem: this.limits.maxQuantityPerItem, attempted: nextQuantity },
      );
    }

    const nowIso = now.toISOString();
    this._items.set(sku, {
      sku,
      name: input.name,
      category: input.category,
      unitPriceMinor: input.unitPrice.amountMinor,
      currency: this.currency,
      quantity: nextQuantity,
      taxExempt: input.taxExempt ?? existing?.taxExempt ?? false,
      addedAt: existing?.addedAt ?? nowIso,
      updatedAt: nowIso,
      metadata: input.metadata ?? existing?.metadata,
    });

    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartItemAdded",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: nowIso,
      payload: {
        sku,
        quantityAdded: input.quantity,
        resultingQuantity: nextQuantity,
        unitPrice: input.unitPrice.toJSON(),
      },
    });
  }

  updateItemQuantity(sku: string, quantity: number, now: Date = new Date()): void {
    this.assertActive("update item in", now);

    if (!Number.isInteger(quantity) || quantity < 0) {
      throw new ValidationError(`Quantity must be a non-negative integer, received: ${quantity}`);
    }

    const existing = this._items.get(sku);
    if (!existing) {
      throw new ValidationError(`SKU "${sku}" is not present in cart "${this.id}"`, { sku });
    }

    if (quantity === 0) {
      this.removeItem(sku, now);
      return;
    }

    if (quantity > this.limits.maxQuantityPerItem) {
      throw new CartLimitExceededError(
        `Quantity for SKU "${sku}" cannot exceed ${this.limits.maxQuantityPerItem}`,
        { sku, maxQuantityPerItem: this.limits.maxQuantityPerItem, attempted: quantity },
      );
    }

    const previousQuantity = existing.quantity;
    if (previousQuantity === quantity) {
      return;
    }

    existing.quantity = quantity;
    existing.updatedAt = now.toISOString();
    this.touch(now);

    this.recordEvent({
      eventId: randomUUID(),
      type: "CartItemQuantityUpdated",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: {
        sku,
        previousQuantity,
        newQuantity: quantity,
      },
    });
  }

  /**
   * Synchronizes cached catalog prices/names on existing items without bumping
   * version unless something actually changed.
   */
  refreshItemPrice(
    sku: string,
    latest: { name: string; category: string; unitPrice: Money; taxExempt?: boolean },
    now: Date = new Date(),
  ): boolean {
    const existing = this._items.get(sku);
    if (!existing) return false;
    if (latest.unitPrice.currency !== this.currency) {
      throw new CurrencyMismatchError(this.currency, latest.unitPrice.currency);
    }

    const changed =
      existing.unitPriceMinor !== latest.unitPrice.amountMinor ||
      existing.name !== latest.name ||
      existing.category !== latest.category ||
      Boolean(existing.taxExempt) !== Boolean(latest.taxExempt);

    if (!changed) return false;

    existing.unitPriceMinor = latest.unitPrice.amountMinor;
    existing.name = latest.name;
    existing.category = latest.category;
    existing.taxExempt = latest.taxExempt ?? false;
    existing.updatedAt = now.toISOString();
    this.touch(now);
    return true;
  }

  removeItem(sku: string, now: Date = new Date()): boolean {
    this.assertActive("remove item from", now);
    const existing = this._items.get(sku);
    if (!existing) {
      return false;
    }

    this._items.delete(sku);
    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartItemRemoved",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: {
        sku,
        removedQuantity: existing.quantity,
      },
    });
    return true;
  }

  clear(now: Date = new Date()): void {
    this.assertActive("clear", now);
    const clearedItemCount = this._items.size;
    if (clearedItemCount === 0 && this._coupons.size === 0) {
      return;
    }

    this._items.clear();
    this._coupons.clear();
    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartCleared",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: { clearedItemCount },
    });
  }

  applyCoupon(rawCode: string, now: Date = new Date()): void {
    this.assertActive("apply coupon to", now);
    const code = rawCode.trim().toUpperCase();
    if (!code) {
      throw new ValidationError("Coupon code cannot be empty");
    }
    if (this._coupons.has(code)) {
      return;
    }
    if (this._coupons.size >= this.limits.maxCoupons) {
      throw new CartLimitExceededError(
        `Cart cannot have more than ${this.limits.maxCoupons} coupons applied`,
        { maxCoupons: this.limits.maxCoupons },
      );
    }

    this._coupons.add(code);
    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartCouponApplied",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: { code },
    });
  }

  removeCoupon(rawCode: string, now: Date = new Date()): boolean {
    this.assertActive("remove coupon from", now);
    const code = rawCode.trim().toUpperCase();
    if (!this._coupons.delete(code)) {
      return false;
    }

    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartCouponRemoved",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: { code },
    });
    return true;
  }

  setShippingRegion(region: string, now: Date = new Date()): void {
    this.assertActive("update shipping region on", now);
    const normalized = region.trim().toUpperCase();
    if (!normalized) {
      throw new ValidationError("Shipping region cannot be empty");
    }
    if (this._shippingRegion === normalized) {
      return;
    }
    this._shippingRegion = normalized;
    this.touch(now);
  }

  assignOwner(ownerId: string, now: Date = new Date()): void {
    this.assertActive("assign owner to", now);
    const trimmed = ownerId.trim();
    if (!trimmed) {
      throw new ValidationError("ownerId cannot be empty");
    }
    if (this._ownerId === trimmed) {
      return;
    }
    this._ownerId = trimmed;
    this.touch(now);
  }

  /**
   * Merges items and coupons from a source cart (typically a guest session cart)
   * into this cart. Quantities are summed up to maxQuantityPerItem.
   */
  mergeFrom(source: Cart, now: Date = new Date()): void {
    this.assertActive("merge into", now);
    source.assertActive("merge from", now);

    if (source.id === this.id) {
      throw new ValidationError("Cannot merge a cart into itself");
    }
    if (source.currency !== this.currency) {
      throw new CurrencyMismatchError(this.currency, source.currency);
    }

    const mergedSkus: string[] = [];
    for (const srcItem of source.items) {
      const existing = this._items.get(srcItem.sku);
      if (!existing && this._items.size >= this.limits.maxDistinctItems) {
        throw new CartLimitExceededError(
          `Merging exceeds maximum distinct SKUs (${this.limits.maxDistinctItems})`,
        );
      }
      const combinedQty = Math.min(
        this.limits.maxQuantityPerItem,
        (existing?.quantity ?? 0) + srcItem.quantity,
      );
      this._items.set(srcItem.sku, {
        ...srcItem,
        quantity: combinedQty,
        addedAt: existing?.addedAt ?? srcItem.addedAt,
        updatedAt: now.toISOString(),
      });
      mergedSkus.push(srcItem.sku);
    }

    for (const coupon of source.coupons) {
      if (this._coupons.size < this.limits.maxCoupons) {
        this._coupons.add(coupon);
      }
    }

    source._status = "MERGED";
    source.touch(now);

    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartMerged",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: {
        sourceCartId: source.id,
        mergedSkus,
      },
    });
  }

  markCheckedOut(
    orderId: string,
    reservationId: string,
    grandTotal: Money,
    now: Date = new Date(),
  ): void {
    this.assertActive("checkout", now);
    if (this._items.size === 0) {
      throw new ValidationError("Cannot checkout an empty cart");
    }

    this._status = "CHECKED_OUT";
    this.touch(now);
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartCheckedOut",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: {
        orderId,
        ownerId: this._ownerId,
        reservationId,
        grandTotal: grandTotal.toJSON(),
        itemCount: this.totalItemUnits,
      },
    });
  }

  markExpired(now: Date = new Date()): void {
    if (this._status !== "ACTIVE") {
      return;
    }
    this._status = "EXPIRED";
    this._version += 1;
    this._updatedAt = now;
    this.recordEvent({
      eventId: randomUUID(),
      type: "CartExpired",
      cartId: this.id,
      cartVersion: this._version,
      occurredAt: now.toISOString(),
      payload: { expiredAt: now.toISOString() },
    });
  }

  pullEvents(): CartDomainEvent[] {
    return this.pendingEvents.splice(0, this.pendingEvents.length);
  }

  toSnapshot(): CartSnapshot {
    return {
      id: this.id,
      ownerId: this._ownerId,
      currency: this.currency,
      status: this._status,
      version: this._version,
      items: this.items.map((item) => ({ ...item })),
      coupons: Array.from(this._coupons),
      shippingRegion: this._shippingRegion,
      metadata: { ...this._metadata },
      createdAt: this.createdAt.toISOString(),
      updatedAt: this._updatedAt.toISOString(),
      expiresAt: this._expiresAt.toISOString(),
    };
  }

  private assertActive(action: string, now: Date): void {
    if (this._status === "ACTIVE" && now.getTime() >= this._expiresAt.getTime()) {
      this._status = "EXPIRED";
    }
    if (this._status !== "ACTIVE") {
      throw new InvalidCartStateError(this.id, this._status, action);
    }
  }

  private touch(now: Date): void {
    this._version += 1;
    this._updatedAt = now;
    // Sliding TTL extension on active mutations
    if (this._status === "ACTIVE") {
      this._expiresAt = new Date(now.getTime() + this.limits.defaultTtlMs);
    }
  }

  private recordEvent(event: CartDomainEvent): void {
    this.pendingEvents.push(event);
  }
}

import type { Cart, CartItemSnapshot } from "./cart.ts";
import { InvalidCouponError } from "./errors.ts";
import { Money, type MoneyJSON } from "./money.ts";

export interface AppliedPromotion {
  readonly ruleId: string;
  readonly description: string;
  readonly couponCode?: string;
  readonly discount: MoneyJSON;
}

export interface PricedLineItem {
  readonly sku: string;
  readonly name: string;
  readonly category: string;
  readonly quantity: number;
  readonly unitPrice: MoneyJSON;
  readonly lineSubtotal: MoneyJSON;
  readonly lineDiscount: MoneyJSON;
  readonly lineTotal: MoneyJSON;
  readonly appliedPromotions: AppliedPromotion[];
}

export interface CartPriceSummary {
  readonly currency: string;
  readonly items: PricedLineItem[];
  readonly subtotal: MoneyJSON;
  readonly lineDiscountTotal: MoneyJSON;
  readonly cartDiscountTotal: MoneyJSON;
  readonly totalDiscount: MoneyJSON;
  readonly taxableAmount: MoneyJSON;
  readonly taxRate: number;
  readonly taxTotal: MoneyJSON;
  readonly shippingTotal: MoneyJSON;
  readonly grandTotal: MoneyJSON;
  readonly appliedPromotions: AppliedPromotion[];
  readonly rejectedCoupons: Array<{ code: string; reason: string }>;
}

export interface PromotionEvaluationContext {
  readonly cart: Cart;
  readonly now: Date;
  readonly items: readonly CartItemSnapshot[];
  readonly lineSubtotals: ReadonlyMap<string, Money>;
  readonly currentLineRemaining: ReadonlyMap<string, Money>;
  readonly currentCartRemaining: Money;
}

export interface PromotionResult {
  readonly lineDiscounts?: Map<string, Money>;
  readonly cartDiscount?: Money;
  readonly freeShipping?: boolean;
}

export interface PromotionRule {
  readonly id: string;
  readonly description: string;
  /** Lower number runs first. */
  readonly priority: number;
  /** If defined, rule only runs when this coupon code is present on the cart. */
  readonly couponCode?: string;
  /** If false, no further non-stackable rules apply after this one triggers. */
  readonly stackable: boolean;
  readonly expiresAt?: Date;
  validateCoupon?(context: PromotionEvaluationContext): string | null;
  evaluate(context: PromotionEvaluationContext): PromotionResult | null;
}

export interface TaxCalculator {
  calculateTax(input: {
    region: string;
    taxableAmount: Money;
  }): { rate: number; tax: Money };
}

export interface ShippingCalculator {
  calculateShipping(input: {
    region: string;
    subtotalAfterDiscounts: Money;
    totalUnits: number;
    freeShippingGranted: boolean;
  }): Money;
}

export class RegionalTaxCalculator implements TaxCalculator {
  private readonly ratesByRegion: Readonly<Record<string, number>>;
  private readonly defaultRate: number;

  constructor(ratesByRegion: Record<string, number> = { ES: 0.21, FR: 0.2, DE: 0.19, US: 0.08 }, defaultRate = 0.21) {
    this.ratesByRegion = { ...ratesByRegion };
    this.defaultRate = defaultRate;
  }

  calculateTax(input: { region: string; taxableAmount: Money }): { rate: number; tax: Money } {
    const rate = this.ratesByRegion[input.region.toUpperCase()] ?? this.defaultRate;
    const tax = input.taxableAmount.multiply(rate);
    return { rate, tax };
  }
}

export class ThresholdShippingCalculator implements ShippingCalculator {
  private readonly flatRateMinor: number;
  private readonly freeShippingThresholdMinor: number;

  constructor(options: { flatRateMinor?: number; freeShippingThresholdMinor?: number } = {}) {
    this.flatRateMinor = options.flatRateMinor ?? 499; // 4.99
    this.freeShippingThresholdMinor = options.freeShippingThresholdMinor ?? 5000; // 50.00
  }

  calculateShipping(input: {
    region: string;
    subtotalAfterDiscounts: Money;
    totalUnits: number;
    freeShippingGranted: boolean;
  }): Money {
    const currency = input.subtotalAfterDiscounts.currency;
    if (input.totalUnits === 0 || input.freeShippingGranted) {
      return Money.zero(currency);
    }
    const threshold = Money.ofMinor(this.freeShippingThresholdMinor, currency);
    if (input.subtotalAfterDiscounts.greaterThanOrEqual(threshold)) {
      return Money.zero(currency);
    }
    return Money.ofMinor(this.flatRateMinor, currency);
  }
}

export class PercentageDiscountRule implements PromotionRule {
  readonly id: string;
  readonly description: string;
  readonly priority: number;
  readonly couponCode?: string;
  readonly stackable: boolean;
  readonly expiresAt?: Date;
  private readonly percent: number;
  private readonly minSubtotalMinor: number;
  private readonly maxDiscountMinor?: number;
  private readonly eligibleCategories?: Set<string>;

  constructor(config: {
    id: string;
    description: string;
    percent: number;
    priority?: number;
    couponCode?: string;
    stackable?: boolean;
    minSubtotalMinor?: number;
    maxDiscountMinor?: number;
    eligibleCategories?: string[];
    expiresAt?: Date;
  }) {
    this.id = config.id;
    this.description = config.description;
    this.percent = config.percent;
    this.priority = config.priority ?? 20;
    this.couponCode = config.couponCode?.trim().toUpperCase();
    this.stackable = config.stackable ?? true;
    this.minSubtotalMinor = config.minSubtotalMinor ?? 0;
    this.maxDiscountMinor = config.maxDiscountMinor;
    this.eligibleCategories = config.eligibleCategories ? new Set(config.eligibleCategories) : undefined;
    this.expiresAt = config.expiresAt;
  }

  validateCoupon(context: PromotionEvaluationContext): string | null {
    if (this.expiresAt && context.now.getTime() > this.expiresAt.getTime()) {
      return "Coupon has expired";
    }
    const min = Money.ofMinor(this.minSubtotalMinor, context.cart.currency);
    if (!context.currentCartRemaining.greaterThanOrEqual(min)) {
      return `Minimum subtotal of ${min.format()} required`;
    }
    return null;
  }

  evaluate(context: PromotionEvaluationContext): PromotionResult | null {
    if (this.validateCoupon(context) !== null) {
      return null;
    }

    const currency = context.cart.currency;
    if (this.eligibleCategories) {
      const lineDiscounts = new Map<string, Money>();
      let accumulated = Money.zero(currency);
      for (const item of context.items) {
        if (!this.eligibleCategories.has(item.category)) continue;
        const remaining = context.currentLineRemaining.get(item.sku) ?? Money.zero(currency);
        let discount = remaining.percentage(this.percent);
        if (this.maxDiscountMinor !== undefined) {
          const cap = Money.ofMinor(this.maxDiscountMinor, currency).subtractClampedZero(accumulated);
          discount = discount.min(cap);
        }
        if (!discount.isZero()) {
          lineDiscounts.set(item.sku, discount);
          accumulated = accumulated.add(discount);
        }
      }
      return lineDiscounts.size > 0 ? { lineDiscounts } : null;
    }

    let discount = context.currentCartRemaining.percentage(this.percent);
    if (this.maxDiscountMinor !== undefined) {
      discount = discount.min(Money.ofMinor(this.maxDiscountMinor, currency));
    }
    return discount.isZero() ? null : { cartDiscount: discount };
  }
}

export class FixedAmountDiscountRule implements PromotionRule {
  readonly id: string;
  readonly description: string;
  readonly priority: number;
  readonly couponCode?: string;
  readonly stackable: boolean;
  readonly expiresAt?: Date;
  private readonly amountMinor: number;
  private readonly currency: string;
  private readonly minSubtotalMinor: number;

  constructor(config: {
    id: string;
    description: string;
    amountMinor: number;
    currency: string;
    priority?: number;
    couponCode?: string;
    stackable?: boolean;
    minSubtotalMinor?: number;
    expiresAt?: Date;
  }) {
    this.id = config.id;
    this.description = config.description;
    this.amountMinor = config.amountMinor;
    this.currency = config.currency.toUpperCase();
    this.priority = config.priority ?? 30;
    this.couponCode = config.couponCode?.trim().toUpperCase();
    this.stackable = config.stackable ?? true;
    this.minSubtotalMinor = config.minSubtotalMinor ?? 0;
    this.expiresAt = config.expiresAt;
  }

  validateCoupon(context: PromotionEvaluationContext): string | null {
    if (context.cart.currency !== this.currency) {
      return `Coupon only valid for currency ${this.currency}`;
    }
    if (this.expiresAt && context.now.getTime() > this.expiresAt.getTime()) {
      return "Coupon has expired";
    }
    const min = Money.ofMinor(this.minSubtotalMinor, this.currency);
    if (!context.currentCartRemaining.greaterThanOrEqual(min)) {
      return `Minimum subtotal of ${min.format()} required`;
    }
    return null;
  }

  evaluate(context: PromotionEvaluationContext): PromotionResult | null {
    if (this.validateCoupon(context) !== null) {
      return null;
    }
    const discount = Money.ofMinor(this.amountMinor, this.currency).min(context.currentCartRemaining);
    return discount.isZero() ? null : { cartDiscount: discount };
  }
}

export class BuyXGetYRule implements PromotionRule {
  readonly id: string;
  readonly description: string;
  readonly priority: number;
  readonly couponCode?: string;
  readonly stackable: boolean;
  readonly expiresAt?: Date;
  private readonly targetSkus?: Set<string>;
  private readonly targetCategories?: Set<string>;
  private readonly buyQuantity: number;
  private readonly freeQuantity: number;

  constructor(config: {
    id: string;
    description: string;
    buyQuantity: number;
    freeQuantity: number;
    targetSkus?: string[];
    targetCategories?: string[];
    priority?: number;
    couponCode?: string;
    stackable?: boolean;
    expiresAt?: Date;
  }) {
    this.id = config.id;
    this.description = config.description;
    this.buyQuantity = config.buyQuantity;
    this.freeQuantity = config.freeQuantity;
    this.targetSkus = config.targetSkus ? new Set(config.targetSkus) : undefined;
    this.targetCategories = config.targetCategories ? new Set(config.targetCategories) : undefined;
    this.priority = config.priority ?? 10;
    this.couponCode = config.couponCode?.trim().toUpperCase();
    this.stackable = config.stackable ?? true;
    this.expiresAt = config.expiresAt;
  }

  evaluate(context: PromotionEvaluationContext): PromotionResult | null {
    if (this.expiresAt && context.now.getTime() > this.expiresAt.getTime()) {
      return null;
    }

    const currency = context.cart.currency;
    const bundleSize = this.buyQuantity + this.freeQuantity;
    const lineDiscounts = new Map<string, Money>();

    for (const item of context.items) {
      const matchesSku = !this.targetSkus || this.targetSkus.has(item.sku);
      const matchesCat = !this.targetCategories || this.targetCategories.has(item.category);
      if (!matchesSku || !matchesCat) continue;

      const eligibleBundles = Math.floor(item.quantity / bundleSize);
      if (eligibleBundles <= 0) continue;

      const freeUnits = eligibleBundles * this.freeQuantity;
      const unitPrice = Money.ofMinor(item.unitPriceMinor, currency);
      const remaining = context.currentLineRemaining.get(item.sku) ?? Money.zero(currency);
      const discount = unitPrice.multiply(freeUnits).min(remaining);
      if (!discount.isZero()) {
        lineDiscounts.set(item.sku, discount);
      }
    }

    return lineDiscounts.size > 0 ? { lineDiscounts } : null;
  }
}

export class BulkTierDiscountRule implements PromotionRule {
  readonly id: string;
  readonly description: string;
  readonly priority: number;
  readonly stackable: boolean;
  private readonly tiers: ReadonlyArray<{ minQuantity: number; percentOff: number }>;
  private readonly eligibleCategories?: Set<string>;

  constructor(config: {
    id: string;
    description: string;
    tiers: Array<{ minQuantity: number; percentOff: number }>;
    eligibleCategories?: string[];
    priority?: number;
    stackable?: boolean;
  }) {
    this.id = config.id;
    this.description = config.description;
    this.tiers = [...config.tiers].sort((a, b) => b.minQuantity - a.minQuantity);
    this.eligibleCategories = config.eligibleCategories ? new Set(config.eligibleCategories) : undefined;
    this.priority = config.priority ?? 15;
    this.stackable = config.stackable ?? true;
  }

  evaluate(context: PromotionEvaluationContext): PromotionResult | null {
    const currency = context.cart.currency;
    const lineDiscounts = new Map<string, Money>();

    for (const item of context.items) {
      if (this.eligibleCategories && !this.eligibleCategories.has(item.category)) continue;
      const matchedTier = this.tiers.find((tier) => item.quantity >= tier.minQuantity);
      if (!matchedTier) continue;

      const remaining = context.currentLineRemaining.get(item.sku) ?? Money.zero(currency);
      const discount = remaining.percentage(matchedTier.percentOff);
      if (!discount.isZero()) {
        lineDiscounts.set(item.sku, discount);
      }
    }

    return lineDiscounts.size > 0 ? { lineDiscounts } : null;
  }
}

export class FreeShippingCouponRule implements PromotionRule {
  readonly id: string;
  readonly description: string;
  readonly priority: number;
  readonly couponCode: string;
  readonly stackable: boolean;
  readonly expiresAt?: Date;

  constructor(config: {
    id: string;
    description: string;
    couponCode: string;
    priority?: number;
    stackable?: boolean;
    expiresAt?: Date;
  }) {
    this.id = config.id;
    this.description = config.description;
    this.couponCode = config.couponCode.trim().toUpperCase();
    this.priority = config.priority ?? 50;
    this.stackable = config.stackable ?? true;
    this.expiresAt = config.expiresAt;
  }

  validateCoupon(context: PromotionEvaluationContext): string | null {
    if (this.expiresAt && context.now.getTime() > this.expiresAt.getTime()) {
      return "Coupon has expired";
    }
    return null;
  }

  evaluate(context: PromotionEvaluationContext): PromotionResult | null {
    if (this.validateCoupon(context) !== null) return null;
    return { freeShipping: true };
  }
}

export class PricingEngine {
  private readonly rules: PromotionRule[];
  private readonly taxCalculator: TaxCalculator;
  private readonly shippingCalculator: ShippingCalculator;

  constructor(options: {
    rules?: PromotionRule[];
    taxCalculator?: TaxCalculator;
    shippingCalculator?: ShippingCalculator;
  } = {}) {
    this.rules = [...(options.rules ?? [])].sort((a, b) => a.priority - b.priority);
    this.taxCalculator = options.taxCalculator ?? new RegionalTaxCalculator();
    this.shippingCalculator = options.shippingCalculator ?? new ThresholdShippingCalculator();
  }

  registerRule(rule: PromotionRule): void {
    this.rules.push(rule);
    this.rules.sort((a, b) => a.priority - b.priority);
  }

  validateCouponExists(code: string): void {
    const normalized = code.trim().toUpperCase();
    const matched = this.rules.some((rule) => rule.couponCode === normalized);
    if (!matched) {
      throw new InvalidCouponError(normalized, "Unknown coupon code");
    }
  }

  calculate(cart: Cart, now: Date = new Date()): CartPriceSummary {
    const currency = cart.currency;
    const items = cart.items;
    const lineSubtotals = new Map<string, Money>();
    const lineDiscountsAcc = new Map<string, Money>();
    const linePromos = new Map<string, AppliedPromotion[]>();
    const currentLineRemaining = new Map<string, Money>();

    let subtotal = Money.zero(currency);

    for (const item of items) {
      const unitPrice = Money.ofMinor(item.unitPriceMinor, currency);
      const lineSub = unitPrice.multiply(item.quantity);
      lineSubtotals.set(item.sku, lineSub);
      lineDiscountsAcc.set(item.sku, Money.zero(currency));
      linePromos.set(item.sku, []);
      currentLineRemaining.set(item.sku, lineSub);
      subtotal = subtotal.add(lineSub);
    }

    let cartDiscountTotal = Money.zero(currency);
    let lineDiscountTotal = Money.zero(currency);
    let freeShippingGranted = false;
    const appliedPromotions: AppliedPromotion[] = [];
    const rejectedCoupons: Array<{ code: string; reason: string }> = [];

    const appliedCouponSet = new Set(cart.coupons);
    const matchedCoupons = new Set<string>();
    let nonStackableApplied = false;

    for (const rule of this.rules) {
      if (rule.couponCode) {
        if (!appliedCouponSet.has(rule.couponCode)) {
          continue;
        }
        matchedCoupons.add(rule.couponCode);
      }

      if (nonStackableApplied && !rule.stackable) {
        if (rule.couponCode) {
          rejectedCoupons.push({
            code: rule.couponCode,
            reason: "Cannot be combined with another non-stackable promotion",
          });
        }
        continue;
      }

      const currentCartRemaining = subtotal
        .subtractClampedZero(lineDiscountTotal)
        .subtractClampedZero(cartDiscountTotal);

      const context: PromotionEvaluationContext = {
        cart,
        now,
        items,
        lineSubtotals,
        currentLineRemaining,
        currentCartRemaining,
      };

      if (rule.couponCode && rule.validateCoupon) {
        const validationError = rule.validateCoupon(context);
        if (validationError) {
          rejectedCoupons.push({ code: rule.couponCode, reason: validationError });
          continue;
        }
      }

      const result = rule.evaluate(context);
      if (!result) continue;

      let ruleTotalDiscount = Money.zero(currency);

      if (result.lineDiscounts) {
        for (const [sku, rawDiscount] of result.lineDiscounts.entries()) {
          const remaining = currentLineRemaining.get(sku);
          if (!remaining || rawDiscount.isZero()) continue;
          const clamped = rawDiscount.min(remaining);
          if (clamped.isZero()) continue;

          currentLineRemaining.set(sku, remaining.subtract(clamped));
          const prevAcc = lineDiscountsAcc.get(sku) ?? Money.zero(currency);
          lineDiscountsAcc.set(sku, prevAcc.add(clamped));
          lineDiscountTotal = lineDiscountTotal.add(clamped);
          ruleTotalDiscount = ruleTotalDiscount.add(clamped);

          linePromos.get(sku)?.push({
            ruleId: rule.id,
            description: rule.description,
            couponCode: rule.couponCode,
            discount: clamped.toJSON(),
          });
        }
      }

      if (result.cartDiscount && !result.cartDiscount.isZero()) {
        const remainingCart = subtotal
          .subtractClampedZero(lineDiscountTotal)
          .subtractClampedZero(cartDiscountTotal);
        const clampedCartDiscount = result.cartDiscount.min(remainingCart);
        if (!clampedCartDiscount.isZero()) {
          cartDiscountTotal = cartDiscountTotal.add(clampedCartDiscount);
          ruleTotalDiscount = ruleTotalDiscount.add(clampedCartDiscount);
        }
      }

      if (result.freeShipping) {
        freeShippingGranted = true;
      }

      if (!ruleTotalDiscount.isZero() || result.freeShipping) {
        appliedPromotions.push({
          ruleId: rule.id,
          description: rule.description,
          couponCode: rule.couponCode,
          discount: ruleTotalDiscount.toJSON(),
        });
        if (!rule.stackable) {
          nonStackableApplied = true;
        }
      }
    }

    for (const coupon of cart.coupons) {
      if (!matchedCoupons.has(coupon)) {
        rejectedCoupons.push({ code: coupon, reason: "Unknown coupon code" });
      }
    }

    const totalDiscount = lineDiscountTotal.add(cartDiscountTotal);
    const subtotalAfterLineDiscounts = subtotal.subtractClampedZero(lineDiscountTotal);
    const subtotalAfterAllDiscounts = subtotal.subtractClampedZero(totalDiscount);

    // Proportionally allocate cart-level discounts across taxable vs tax-exempt lines
    let taxableAfterLine = Money.zero(currency);
    for (const item of items) {
      if (item.taxExempt) continue;
      taxableAfterLine = taxableAfterLine.add(currentLineRemaining.get(item.sku) ?? Money.zero(currency));
    }

    let taxableAmount = taxableAfterLine;
    if (!subtotalAfterLineDiscounts.isZero() && !cartDiscountTotal.isZero()) {
      const taxableRatio = taxableAfterLine.amountMinor / subtotalAfterLineDiscounts.amountMinor;
      const taxableCartDiscount = cartDiscountTotal.multiply(taxableRatio);
      taxableAmount = taxableAfterLine.subtractClampedZero(taxableCartDiscount);
    }

    const { rate: taxRate, tax: taxTotal } = this.taxCalculator.calculateTax({
      region: cart.shippingRegion,
      taxableAmount,
    });

    const shippingTotal = this.shippingCalculator.calculateShipping({
      region: cart.shippingRegion,
      subtotalAfterDiscounts: subtotalAfterAllDiscounts,
      totalUnits: cart.totalItemUnits,
      freeShippingGranted,
    });

    const grandTotal = subtotalAfterAllDiscounts.add(taxTotal).add(shippingTotal);

    const pricedItems: PricedLineItem[] = items.map((item) => {
      const unitPrice = Money.ofMinor(item.unitPriceMinor, currency);
      const lineSub = lineSubtotals.get(item.sku) ?? Money.zero(currency);
      const lineDisc = lineDiscountsAcc.get(item.sku) ?? Money.zero(currency);
      const lineTot = lineSub.subtractClampedZero(lineDisc);

      return {
        sku: item.sku,
        name: item.name,
        category: item.category,
        quantity: item.quantity,
        unitPrice: unitPrice.toJSON(),
        lineSubtotal: lineSub.toJSON(),
        lineDiscount: lineDisc.toJSON(),
        lineTotal: lineTot.toJSON(),
        appliedPromotions: linePromos.get(item.sku) ?? [],
      };
    });

    return {
      currency,
      items: pricedItems,
      subtotal: subtotal.toJSON(),
      lineDiscountTotal: lineDiscountTotal.toJSON(),
      cartDiscountTotal: cartDiscountTotal.toJSON(),
      totalDiscount: totalDiscount.toJSON(),
      taxableAmount: taxableAmount.toJSON(),
      taxRate,
      taxTotal: taxTotal.toJSON(),
      shippingTotal: shippingTotal.toJSON(),
      grandTotal: grandTotal.toJSON(),
      appliedPromotions,
      rejectedCoupons,
    };
  }
}

import type { CartSnapshot } from "../domain/cart.ts";

/**
 * Persistence Port for Cart aggregates.
 * Implementations (Redis, PostgreSQL, DynamoDB, File, In-Memory) MUST enforce
 * optimistic concurrency control using `expectedVersion` (0 for new carts).
 */
export interface CartRepository {
  findById(cartId: string): Promise<CartSnapshot | null>;
  findActiveByOwner(ownerId: string): Promise<CartSnapshot | null>;
  /**
   * Persists a cart snapshot only if the stored version equals `expectedVersion`.
   * Pass `expectedVersion = 0` when creating a new cart.
   * Throws `ConcurrencyConflictError` if another writer mutated the cart concurrently.
   */
  save(snapshot: CartSnapshot, expectedVersion: number): Promise<void>;
  delete(cartId: string): Promise<boolean>;
  /**
   * Finds and marks/removes expired carts so storage does not grow unboundedly.
   * Returns the expired cart snapshots (or IDs) that were purged/marked.
   */
  purgeExpired(now: Date): Promise<CartSnapshot[]>;
}

import type { Money } from "../domain/money.ts";

export interface CatalogProduct {
  readonly sku: string;
  readonly name: string;
  readonly category: string;
  readonly price: Money;
  readonly active: boolean;
  readonly taxExempt?: boolean;
  readonly metadata?: Record<string, string>;
}

/**
 * Product Catalog Port.
 * Exposes batch lookup (`getProducts`) to prevent N+1 queries during cart hydration and checkout.
 */
export interface CatalogProvider {
  getProduct(sku: string): Promise<CatalogProduct | null>;
  getProducts(skus: readonly string[]): Promise<Map<string, CatalogProduct>>;
}

export interface StockItemRequest {
  readonly sku: string;
  readonly quantity: number;
}

export interface StockReservation {
  readonly reservationId: string;
  readonly cartId: string;
  readonly items: readonly StockItemRequest[];
  readonly expiresAt: string;
}

/**
 * Inventory Port for real-time availability checks and atomic checkout reservations.
 */
export interface InventoryProvider {
  getAvailableStock(sku: string): Promise<number>;
  getAvailableStockBatch(skus: readonly string[]): Promise<Map<string, number>>;
  /**
   * Atomically reserves stock for all requested SKUs, or fails with `InsufficientStockError`
   * without partially reserving any SKU.
   */
  reserve(
    cartId: string,
    items: readonly StockItemRequest[],
    ttlMs?: number,
  ): Promise<StockReservation>;
  releaseReservation(reservationId: string): Promise<void>;
  commitReservation(reservationId: string): Promise<void>;
}

import type { CartDomainEvent } from "../domain/events.ts";

export type EventHandler<TEvent extends CartDomainEvent = CartDomainEvent> = (
  event: TEvent,
) => void | Promise<void>;

/**
 * Event Bus Port for decoupling cart mutations from downstream consumers
 * (analytics, abandoned-cart emails, order management, warehouse fulfillment).
 */
export interface EventBus {
  publish(events: readonly CartDomainEvent[]): Promise<void>;
  subscribe<TType extends CartDomainEvent["type"]>(
    eventType: TType,
    handler: EventHandler<Extract<CartDomainEvent, { type: TType }>>,
  ): () => void;
  subscribeAll(handler: EventHandler<CartDomainEvent>): () => void;
}

export interface IdempotencyRecord<TResult = unknown> {
  readonly key: string;
  readonly requestHash: string;
  readonly result: TResult;
  readonly createdAt: number;
  readonly expiresAt: number;
}

/**
 * Idempotency Store Port.
 * Prevents duplicate side effects when clients or load balancers retry requests.
 */
export interface IdempotencyStore {
  execute<TResult>(
    key: string,
    requestFingerprint: string,
    ttlMs: number,
    operation: () => Promise<TResult>,
  ): Promise<{ result: TResult; replayed: boolean }>;
}

/**
 * Distributed Lock Manager Port (e.g., Redlock / Redis SET NX / Postgres advisory locks).
 * Coordinates concurrent mutations targeting the same cart key while keeping
 * different carts fully parallel.
 */
export interface LockManager {
  withLock<T>(key: string, fn: () => Promise<T>, options?: { timeoutMs?: number }): Promise<T>;
}

import type { CartSnapshot } from "../domain/cart.ts";
import { ConcurrencyConflictError } from "../domain/errors.ts";
import type { CartRepository } from "../ports/cart-repository.ts";

function cloneSnapshot(snapshot: CartSnapshot): CartSnapshot {
  return structuredClone(snapshot);
}

/**
 * In-memory CartRepository with strict Optimistic Concurrency Control (OCC).
 * Suitable for unit/integration tests and single-instance development.
 * Replace with a Redis/PostgreSQL adapter implementing the exact same contract for multi-node production.
 */
export class InMemoryCartRepository implements CartRepository {
  private readonly carts = new Map<string, CartSnapshot>();

  async findById(cartId: string): Promise<CartSnapshot | null> {
    const found = this.carts.get(cartId);
    return found ? cloneSnapshot(found) : null;
  }

  async findActiveByOwner(ownerId: string): Promise<CartSnapshot | null> {
    let latest: CartSnapshot | null = null;
    for (const cart of this.carts.values()) {
      if (cart.ownerId === ownerId && cart.status === "ACTIVE") {
        if (!latest || cart.updatedAt > latest.updatedAt) {
          latest = cart;
        }
      }
    }
    return latest ? cloneSnapshot(latest) : null;
  }

  async save(snapshot: CartSnapshot, expectedVersion: number): Promise<void> {
    const existing = this.carts.get(snapshot.id);
    const actualVersion = existing ? existing.version : 0;

    if (actualVersion !== expectedVersion) {
      throw new ConcurrencyConflictError(snapshot.id, expectedVersion, actualVersion);
    }

    this.carts.set(snapshot.id, cloneSnapshot(snapshot));
  }

  async delete(cartId: string): Promise<boolean> {
    return this.carts.delete(cartId);
  }

  async purgeExpired(now: Date): Promise<CartSnapshot[]> {
    const expired: CartSnapshot[] = [];
    const nowMs = now.getTime();

    for (const [id, snapshot] of this.carts.entries()) {
      if (snapshot.status === "ACTIVE" && new Date(snapshot.expiresAt).getTime() <= nowMs) {
        const updated: CartSnapshot = {
          ...cloneSnapshot(snapshot),
          status: "EXPIRED",
          version: snapshot.version + 1,
          updatedAt: now.toISOString(),
        };
        this.carts.set(id, updated);
        expired.push(cloneSnapshot(updated));
      }
    }

    return expired;
  }

  count(): number {
    return this.carts.size;
  }
}

import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import type { CartSnapshot } from "../domain/cart.ts";
import { ConcurrencyConflictError } from "../domain/errors.ts";
import type { CartRepository } from "../ports/cart-repository.ts";

interface PersistedData {
  carts: Record<string, CartSnapshot>;
}

/**
 * Durable JSON-file CartRepository using atomic temp-file + rename writes.
 * Preserves optimistic concurrency checks and survives process restarts without
 * requiring an external database server.
 */
export class FileCartRepository implements CartRepository {
  private readonly filePath: string;
  private writeChain: Promise<void> = Promise.resolve();

  constructor(filePath: string) {
    this.filePath = filePath;
  }

  async findById(cartId: string): Promise<CartSnapshot | null> {
    const data = await this.readStore();
    const found = data.carts[cartId];
    return found ? structuredClone(found) : null;
  }

  async findActiveByOwner(ownerId: string): Promise<CartSnapshot | null> {
    const data = await this.readStore();
    let latest: CartSnapshot | null = null;
    for (const cart of Object.values(data.carts)) {
      if (cart.ownerId === ownerId && cart.status === "ACTIVE") {
        if (!latest || cart.updatedAt > latest.updatedAt) {
          latest = cart;
        }
      }
    }
    return latest ? structuredClone(latest) : null;
  }

  async save(snapshot: CartSnapshot, expectedVersion: number): Promise<void> {
    await this.enqueueWrite(async () => {
      const data = await this.readStore();
      const existing = data.carts[snapshot.id];
      const actualVersion = existing ? existing.version : 0;

      if (actualVersion !== expectedVersion) {
        throw new ConcurrencyConflictError(snapshot.id, expectedVersion, actualVersion);
      }

      data.carts[snapshot.id] = structuredClone(snapshot);
      await this.writeStore(data);
    });
  }

  async delete(cartId: string): Promise<boolean> {
    let deleted = false;
    await this.enqueueWrite(async () => {
      const data = await this.readStore();
      if (cartId in data.carts) {
        delete data.carts[cartId];
        deleted = true;
        await this.writeStore(data);
      }
    });
    return deleted;
  }

  async purgeExpired(now: Date): Promise<CartSnapshot[]> {
    const expired: CartSnapshot[] = [];
    await this.enqueueWrite(async () => {
      const data = await this.readStore();
      const nowMs = now.getTime();
      let changed = false;

      for (const [id, snapshot] of Object.entries(data.carts)) {
        if (snapshot.status === "ACTIVE" && new Date(snapshot.expiresAt).getTime() <= nowMs) {
          const updated: CartSnapshot = {
            ...structuredClone(snapshot),
            status: "EXPIRED",
            version: snapshot.version + 1,
            updatedAt: now.toISOString(),
          };
          data.carts[id] = updated;
          expired.push(structuredClone(updated));
          changed = true;
        }
      }

      if (changed) {
        await this.writeStore(data);
      }
    });
    return expired;
  }

  private async enqueueWrite(task: () => Promise<void>): Promise<void> {
    const previous = this.writeChain;
    let release!: () => void;
    this.writeChain = new Promise<void>((resolve) => {
      release = resolve;
    });
    await previous;
    try {
      await task();
    } finally {
      release();
    }
  }

  private async readStore(): Promise<PersistedData> {
    try {
      const raw = await readFile(this.filePath, "utf-8");
      const parsed = JSON.parse(raw) as Partial<PersistedData>;
      return { carts: parsed.carts ?? {} };
    } catch {
      return { carts: {} };
    }
  }

  private async writeStore(data: PersistedData): Promise<void> {
    await mkdir(dirname(this.filePath), { recursive: true });
    const tmpPath = `${this.filePath}.${Date.now()}.${Math.random().toString(16).slice(2)}.tmp`;
    await writeFile(tmpPath, JSON.stringify(data, null, 2), "utf-8");
    await rename(tmpPath, this.filePath);
  }
}

