import { randomUUID } from "node:crypto";
import { InsufficientStockError } from "../domain/errors.ts";
import type {
  InventoryProvider,
  StockItemRequest,
  StockReservation,
} from "../ports/inventory-provider.ts";

interface InternalReservation {
  readonly reservationId: string;
  readonly cartId: string;
  readonly items: readonly StockItemRequest[];
  readonly expiresAtMs: number;
  state: "RESERVED" | "COMMITTED" | "RELEASED";
}

/**
 * In-memory InventoryProvider with atomic all-or-nothing reservations
 * and automatic expiration of stale holds.
 */
export class InMemoryInventoryProvider implements InventoryProvider {
  private readonly totalStock = new Map<string, number>();
  private readonly reservations = new Map<string, InternalReservation>();
  private readonly defaultReservationTtlMs: number;

  constructor(
    initialStock: Record<string, number> = {},
    options: { defaultReservationTtlMs?: number } = {},
  ) {
    for (const [sku, qty] of Object.entries(initialStock)) {
      this.totalStock.set(sku, qty);
    }
    this.defaultReservationTtlMs = options.defaultReservationTtlMs ?? 15 * 60 * 1000;
  }

  setStock(sku: string, quantity: number): void {
    this.totalStock.set(sku, Math.max(0, quantity));
  }

  async getAvailableStock(sku: string): Promise<number> {
    this.cleanupExpiredReservations();
    const total = this.totalStock.get(sku) ?? 0;
    const reserved = this.getReservedCount(sku);
    return Math.max(0, total - reserved);
  }

  async getAvailableStockBatch(skus: readonly string[]): Promise<Map<string, number>> {
    this.cleanupExpiredReservations();
    const result = new Map<string, number>();
    for (const sku of skus) {
      const total = this.totalStock.get(sku) ?? 0;
      const reserved = this.getReservedCount(sku);
      result.set(sku, Math.max(0, total - reserved));
    }
    return result;
  }

  async reserve(
    cartId: string,
    items: readonly StockItemRequest[],
    ttlMs: number = this.defaultReservationTtlMs,
  ): Promise<StockReservation> {
    this.cleanupExpiredReservations();

    // Aggregate quantities per SKU in case duplicates appear
    const needed = new Map<string, number>();
    for (const item of items) {
      needed.set(item.sku, (needed.get(item.sku) ?? 0) + item.quantity);
    }

    // Phase 1: Validate all SKUs before reserving any (all-or-nothing)
    for (const [sku, qty] of needed.entries()) {
      const total = this.totalStock.get(sku) ?? 0;
      const available = Math.max(0, total - this.getReservedCount(sku));
      if (available < qty) {
        throw new InsufficientStockError(sku, qty, available);
      }
    }

    // Phase 2: Create reservation
    const reservationId = `res_${randomUUID()}`;
    const expiresAtMs = Date.now() + ttlMs;
    const normalizedItems: StockItemRequest[] = Array.from(needed.entries(), ([sku, quantity]) => ({
      sku,
      quantity,
    }));

    this.reservations.set(reservationId, {
      reservationId,
      cartId,
      items: normalizedItems,
      expiresAtMs,
      state: "RESERVED",
    });

    return {
      reservationId,
      cartId,
      items: normalizedItems,
      expiresAt: new Date(expiresAtMs).toISOString(),
    };
  }

  async releaseReservation(reservationId: string): Promise<void> {
    const reservation = this.reservations.get(reservationId);
    if (!reservation || reservation.state !== "RESERVED") return;
    reservation.state = "RELEASED";
    this.reservations.delete(reservationId);
  }

  async commitReservation(reservationId: string): Promise<void> {
    this.cleanupExpiredReservations();
    const reservation = this.reservations.get(reservationId);
    if (!reservation || reservation.state !== "RESERVED") return;

    for (const item of reservation.items) {
      const current = this.totalStock.get(item.sku) ?? 0;
      this.totalStock.set(item.sku, Math.max(0, current - item.quantity));
    }
    reservation.state = "COMMITTED";
    this.reservations.delete(reservationId);
  }

  private getReservedCount(sku: string): number {
    let sum = 0;
    for (const res of this.reservations.values()) {
      if (res.state !== "RESERVED") continue;
      for (const item of res.items) {
        if (item.sku === sku) {
          sum += item.quantity;
        }
      }
    }
    return sum;
  }

  private cleanupExpiredReservations(): void {
    const now = Date.now();
    for (const [id, res] of this.reservations.entries()) {
      if (res.state === "RESERVED" && res.expiresAtMs <= now) {
        this.reservations.delete(id);
      }
    }
  }
}

import type { CartDomainEvent } from "../domain/events.ts";
import type { EventBus, EventHandler } from "../ports/event-bus.ts";

/**
 * In-memory asynchronous EventBus with subscriber error isolation.
 * In production, swap this adapter with Kafka, RabbitMQ, AWS EventBridge, or Redis Streams.
 */
export class InMemoryEventBus implements EventBus {
  private readonly handlersByType = new Map<string, Set<EventHandler>>();
  private readonly wildcardHandlers = new Set<EventHandler>();
  private readonly onHandlerError?: (error: unknown, event: CartDomainEvent) => void;

  constructor(options: { onHandlerError?: (error: unknown, event: CartDomainEvent) => void } = {}) {
    this.onHandlerError = options.onHandlerError;
  }

  async publish(events: readonly CartDomainEvent[]): Promise<void> {
    for (const event of events) {
      const specific = this.handlersByType.get(event.type);
      const targets: EventHandler[] = [
        ...(specific ? Array.from(specific) : []),
        ...Array.from(this.wildcardHandlers),
      ];

      await Promise.all(
        targets.map(async (handler) => {
          try {
            await handler(event);
          } catch (error) {
            if (this.onHandlerError) {
              this.onHandlerError(error, event);
            }
          }
        }),
      );
    }
  }

  subscribe<TType extends CartDomainEvent["type"]>(
    eventType: TType,
    handler: EventHandler<Extract<CartDomainEvent, { type: TType }>>,
  ): () => void {
    let set = this.handlersByType.get(eventType);
    if (!set) {
      set = new Set();
      this.handlersByType.set(eventType, set);
    }
    const wrapped = handler as EventHandler;
    set.add(wrapped);
    return () => {
      set.delete(wrapped);
    };
  }

  subscribeAll(handler: EventHandler<CartDomainEvent>): () => void {
    this.wildcardHandlers.add(handler);
    return () => {
      this.wildcardHandlers.delete(handler);
    };
  }
}

import { createHash } from "node:crypto";
import { IdempotencyConflictError } from "../domain/errors.ts";
import type { IdempotencyRecord, IdempotencyStore } from "../ports/idempotency-store.ts";

interface InFlightEntry {
  requestHash: string;
  promise: Promise<unknown>;
}

/**
 * In-memory IdempotencyStore supporting:
 * 1. Replay of completed results within TTL.
 * 2. In-flight deduplication for concurrent retries with the same key.
 * 3. Payload mismatch rejection if the same key is reused with different parameters.
 */
export class InMemoryIdempotencyStore implements IdempotencyStore {
  private readonly completed = new Map<string, IdempotencyRecord>();
  private readonly inFlight = new Map<string, InFlightEntry>();

  async execute<TResult>(
    key: string,
    requestFingerprint: string,
    ttlMs: number,
    operation: () => Promise<TResult>,
  ): Promise<{ result: TResult; replayed: boolean }> {
    this.evictExpired();

    const requestHash = createHash("sha256").update(requestFingerprint).digest("hex");

    const cached = this.completed.get(key);
    if (cached) {
      if (cached.requestHash !== requestHash) {
        throw new IdempotencyConflictError(key, "Key was already used with a different request payload");
      }
      return { result: structuredClone(cached.result) as TResult, replayed: true };
    }

    const active = this.inFlight.get(key);
    if (active) {
      if (active.requestHash !== requestHash) {
        throw new IdempotencyConflictError(
          key,
          "Concurrent request uses the same key with a different payload",
        );
      }
      const result = (await active.promise) as TResult;
      return { result: structuredClone(result), replayed: true };
    }

    const promise = operation();
    this.inFlight.set(key, { requestHash, promise });

    try {
      const result = await promise;
      const now = Date.now();
      this.completed.set(key, {
        key,
        requestHash,
        result: structuredClone(result),
        createdAt: now,
        expiresAt: now + ttlMs,
      });
      return { result, replayed: false };
    } finally {
      this.inFlight.delete(key);
    }
  }

  private evictExpired(): void {
    const now = Date.now();
    for (const [key, record] of this.completed.entries()) {
      if (record.expiresAt <= now) {
        this.completed.delete(key);
      }
    }
  }
}

import { LockTimeoutError } from "../domain/errors.ts";
import type { LockManager } from "../ports/lock-manager.ts";

/**
 * Per-key asynchronous mutex implementing LockManager.
 * Serializes concurrent mutations on the *same* cart while allowing
 * thousands of *different* carts to execute completely in parallel.
 */
export class InMemoryLockManager implements LockManager {
  private readonly queues = new Map<string, Promise<void>>();
  private readonly defaultTimeoutMs: number;

  constructor(options: { defaultTimeoutMs?: number } = {}) {
    this.defaultTimeoutMs = options.defaultTimeoutMs ?? 5000;
  }

  async withLock<T>(
    key: string,
    fn: () => Promise<T>,
    options?: { timeoutMs?: number },
  ): Promise<T> {
    const timeoutMs = options?.timeoutMs ?? this.defaultTimeoutMs;
    const previous = this.queues.get(key) ?? Promise.resolve();

    let release!: () => void;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });

    const tail = previous.then(() => current);
    this.queues.set(key, tail);

    let acquired = false;
    try {
      await this.waitWithTimeout(previous, key, timeoutMs);
      acquired = true;
      return await fn();
    } finally {
      release();
      if (this.queues.get(key) === tail) {
        this.queues.delete(key);
      }
      if (!acquired) {
        // Ensure chain does not leak rejection if timed out before previous resolved
        void previous.catch(() => {});
      }
    }
  }

  private async waitWithTimeout(promise: Promise<void>, key: string, timeoutMs: number): Promise<void> {
    let timer: unknown;
    const timeoutPromise = new Promise<never>((_, reject) => {
      timer = setTimeout(() => {
        reject(new LockTimeoutError(key, timeoutMs));
      }, timeoutMs);
    });

    try {
      await Promise.race([promise, timeoutPromise]);
    } finally {
      clearTimeout(timer);
    }
  }
}

import { randomUUID } from "node:crypto";
import {
  Cart,
  DEFAULT_CART_LIMITS,
  type CartLimits,
  type CartSnapshot,
} from "../domain/cart.ts";
import {
  CartNotFoundError,
  ConcurrencyConflictError,
  InsufficientStockError,
  ProductNotFoundError,
  ValidationError,
} from "../domain/errors.ts";
import type { CartDomainEvent } from "../domain/events.ts";
import { Money } from "../domain/money.ts";
import { PricingEngine, type CartPriceSummary } from "../domain/pricing.ts";
import type { CartRepository } from "../ports/cart-repository.ts";
import type { CatalogProvider } from "../ports/catalog-provider.ts";
import type { EventBus } from "../ports/event-bus.ts";
import type { IdempotencyStore } from "../ports/idempotency-store.ts";
import type { InventoryProvider } from "../ports/inventory-provider.ts";
import type { LockManager } from "../ports/lock-manager.ts";

export interface CartView {
  readonly cart: CartSnapshot;
  readonly pricing: CartPriceSummary;
}

export interface CommandOptions {
  readonly idempotencyKey?: string;
  /** Optional explicit optimistic lock version (e.g. from HTTP If-Match). */
  readonly expectedVersion?: number;
}

export interface CreateCartCommand {
  readonly ownerId?: string | null;
  readonly currency?: string;
  readonly shippingRegion?: string;
  readonly ttlMs?: number;
  readonly metadata?: Record<string, string>;
  readonly idempotencyKey?: string;
}

export interface AddItemCommand extends CommandOptions {
  readonly cartId: string;
  readonly sku: string;
  readonly quantity: number;
  readonly metadata?: Record<string, string>;
}

export interface UpdateItemQuantityCommand extends CommandOptions {
  readonly cartId: string;
  readonly sku: string;
  readonly quantity: number;
}

export interface RemoveItemCommand extends CommandOptions {
  readonly cartId: string;
  readonly sku: string;
}

export interface CouponCommand extends CommandOptions {
  readonly cartId: string;
  readonly code: string;
}

export interface MergeCartsCommand {
  readonly sourceCartId: string;
  readonly targetCartId: string;
  readonly idempotencyKey?: string;
}

export interface CheckoutCommand extends CommandOptions {
  readonly cartId: string;
  readonly commitInventoryImmediately?: boolean;
}

export interface CheckoutResult {
  readonly orderId: string;
  readonly reservationId: string;
  readonly cart: CartSnapshot;
  readonly pricing: CartPriceSummary;
  readonly checkedOutAt: string;
}

export interface CartServiceDependencies {
  readonly repository: CartRepository;
  readonly catalog: CatalogProvider;
  readonly inventory: InventoryProvider;
  readonly pricingEngine: PricingEngine;
  readonly eventBus: EventBus;
  readonly idempotencyStore: IdempotencyStore;
  readonly lockManager: LockManager;
  readonly limits?: CartLimits;
  readonly maxOptimisticRetries?: number;
  readonly idempotencyTtlMs?: number;
  readonly clock?: () => Date;
}

export class CartService {
  private readonly repository: CartRepository;
  private readonly catalog: CatalogProvider;
  private readonly inventory: InventoryProvider;
  private readonly pricingEngine: PricingEngine;
  private readonly eventBus: EventBus;
  private readonly idempotencyStore: IdempotencyStore;
  private readonly lockManager: LockManager;
  private readonly limits: CartLimits;
  private readonly maxOptimisticRetries: number;
  private readonly idempotencyTtlMs: number;
  private readonly clock: () => Date;

  constructor(deps: CartServiceDependencies) {
    this.repository = deps.repository;
    this.catalog = deps.catalog;
    this.inventory = deps.inventory;
    this.pricingEngine = deps.pricingEngine;
    this.eventBus = deps.eventBus;
    this.idempotencyStore = deps.idempotencyStore;
    this.lockManager = deps.lockManager;
    this.limits = deps.limits ?? DEFAULT_CART_LIMITS;
    this.maxOptimisticRetries = deps.maxOptimisticRetries ?? 3;
    this.idempotencyTtlMs = deps.idempotencyTtlMs ?? 24 * 60 * 60 * 1000;
    this.clock = deps.clock ?? (() => new Date());
  }

  async createCart(cmd: CreateCartCommand = {}): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `createCart:${JSON.stringify({
        ownerId: cmd.ownerId ?? null,
        currency: cmd.currency ?? "EUR",
        shippingRegion: cmd.shippingRegion ?? "ES",
        metadata: cmd.metadata ?? {},
      })}`,
      async () => {
        const now = this.clock();
        const cart = Cart.create(
          {
            ownerId: cmd.ownerId,
            currency: cmd.currency,
            shippingRegion: cmd.shippingRegion,
            ttlMs: cmd.ttlMs,
            metadata: cmd.metadata,
            now,
          },
          this.limits,
        );

        await this.repository.save(cart.toSnapshot(), 0);
        await this.publishPending(cart);
        return this.buildView(cart, now);
      },
    );
  }

  async getOrCreateOwnerCart(
    ownerId: string,
    defaults: Omit<CreateCartCommand, "ownerId"> = {},
  ): Promise<CartView> {
    const trimmedOwner = ownerId.trim();
    if (!trimmedOwner) {
      throw new ValidationError("ownerId must be a non-empty string");
    }

    return this.lockManager.withLock(`owner:${trimmedOwner}`, async () => {
      const existing = await this.repository.findActiveByOwner(trimmedOwner);
      const now = this.clock();
      if (existing) {
        const cart = Cart.fromSnapshot(existing, this.limits);
        if (!cart.isExpired(now)) {
          return this.buildView(cart, now);
        }
      }
      return this.createCart({ ...defaults, ownerId: trimmedOwner });
    });
  }

  async getCart(cartId: string, options: { refreshPrices?: boolean } = {}): Promise<CartView> {
    const now = this.clock();
    if (!options.refreshPrices) {
      const cart = await this.loadCartOrThrow(cartId);
      return this.buildView(cart, now);
    }

    return this.mutateCart(cartId, undefined, async (cart) => {
      if (cart.status === "ACTIVE" && !cart.isExpired(now) && cart.items.length > 0) {
        await this.syncCatalogPrices(cart, now);
      }
    });
  }

  async addItem(cmd: AddItemCommand): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `addItem:${cmd.cartId}:${cmd.sku}:${cmd.quantity}:${JSON.stringify(cmd.metadata ?? {})}`,
      async () => {
        const product = await this.catalog.getProduct(cmd.sku);
        if (!product) {
          throw new ProductNotFoundError(cmd.sku);
        }

        return this.mutateCart(cmd.cartId, cmd.expectedVersion, async (cart, now) => {
          const existingQty = cart.getItem(cmd.sku)?.quantity ?? 0;
          const desiredQty = existingQty + cmd.quantity;
          const available = await this.inventory.getAvailableStock(cmd.sku);
          if (available < desiredQty) {
            throw new InsufficientStockError(cmd.sku, desiredQty, available);
          }

          cart.addItem({
            sku: product.sku,
            name: product.name,
            category: product.category,
            unitPrice: product.price,
            quantity: cmd.quantity,
            taxExempt: product.taxExempt,
            metadata: cmd.metadata,
            now,
          });
        });
      },
    );
  }

  async updateItemQuantity(cmd: UpdateItemQuantityCommand): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `updateQty:${cmd.cartId}:${cmd.sku}:${cmd.quantity}`,
      async () => {
        return this.mutateCart(cmd.cartId, cmd.expectedVersion, async (cart, now) => {
          if (cmd.quantity > 0) {
            const available = await this.inventory.getAvailableStock(cmd.sku);
            if (available < cmd.quantity) {
              throw new InsufficientStockError(cmd.sku, cmd.quantity, available);
            }
          }
          cart.updateItemQuantity(cmd.sku, cmd.quantity, now);
        });
      },
    );
  }

  async removeItem(cmd: RemoveItemCommand): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `removeItem:${cmd.cartId}:${cmd.sku}`,
      async () => {
        return this.mutateCart(cmd.cartId, cmd.expectedVersion, async (cart, now) => {
          cart.removeItem(cmd.sku, now);
        });
      },
    );
  }

  async clearCart(cartId: string, options: CommandOptions = {}): Promise<CartView> {
    return this.withOptionalIdempotency(
      options.idempotencyKey,
      `clearCart:${cartId}`,
      async () => {
        return this.mutateCart(cartId, options.expectedVersion, async (cart, now) => {
          cart.clear(now);
        });
      },
    );
  }

  async applyCoupon(cmd: CouponCommand): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `applyCoupon:${cmd.cartId}:${cmd.code.trim().toUpperCase()}`,
      async () => {
        this.pricingEngine.validateCouponExists(cmd.code);
        return this.mutateCart(cmd.cartId, cmd.expectedVersion, async (cart, now) => {
          cart.applyCoupon(cmd.code, now);
        });
      },
    );
  }

  async removeCoupon(cmd: CouponCommand): Promise<CartView> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `removeCoupon:${cmd.cartId}:${cmd.code.trim().toUpperCase()}`,
      async () => {
        return this.mutateCart(cmd.cartId, cmd.expectedVersion, async (cart, now) => {
          cart.removeCoupon(cmd.code, now);
        });
      },
    );
  }

  async setShippingRegion(
    cartId: string,
    shippingRegion: string,
    options: CommandOptions = {},
  ): Promise<CartView> {
    return this.mutateCart(cartId, options.expectedVersion, async (cart, now) => {
      cart.setShippingRegion(shippingRegion, now);
    });
  }

  /**
   * Merges a guest cart into a target (e.g. authenticated user) cart.
   * Acquires locks in lexicographic order to eliminate deadlock risk under concurrent merges.
   */
  async mergeCarts(cmd: MergeCartsCommand): Promise<CartView> {
    if (cmd.sourceCartId === cmd.targetCartId) {
      throw new ValidationError("sourceCartId and targetCartId must be different");
    }

    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `merge:${cmd.sourceCartId}->${cmd.targetCartId}`,
      async () => {
        const [firstId, secondId] = [cmd.sourceCartId, cmd.targetCartId].sort();
        return this.lockManager.withLock(`cart:${firstId}`, async () =>
          this.lockManager.withLock(`cart:${secondId}`, async () => {
            const now = this.clock();
            const source = await this.loadCartOrThrow(cmd.sourceCartId);
            const target = await this.loadCartOrThrow(cmd.targetCartId);

            const sourceExpectedVersion = source.version;
            const targetExpectedVersion = target.version;

            // Validate inventory in batch for combined quantities
            const combinedSkus = new Set<string>([
              ...source.items.map((i) => i.sku),
              ...target.items.map((i) => i.sku),
            ]);
            const stockMap = await this.inventory.getAvailableStockBatch(Array.from(combinedSkus));
            for (const srcItem of source.items) {
              const targetQty = target.getItem(srcItem.sku)?.quantity ?? 0;
              const desired = Math.min(this.limits.maxQuantityPerItem, targetQty + srcItem.quantity);
              const available = stockMap.get(srcItem.sku) ?? 0;
              if (available < desired) {
                throw new InsufficientStockError(srcItem.sku, desired, available);
              }
            }

            target.mergeFrom(source, now);

            // Persist target first, then source (if target fails, source remains untouched)
            await this.repository.save(target.toSnapshot(), targetExpectedVersion);
            await this.repository.save(source.toSnapshot(), sourceExpectedVersion);

            await this.publishPending(target);
            await this.publishPending(source);
            return this.buildView(target, now);
          }),
        );
      },
    );
  }

  /**
   * Executes cart checkout:
   * 1. Refreshes authoritative catalog prices in a single batch call.
   * 2. Atomically reserves inventory for all cart items.
   * 3. Computes final price summary.
   * 4. Marks cart CHECKED_OUT and persists with optimistic lock.
   * 5. Compensates (releases stock reservation) if persistence fails.
   */
  async checkout(cmd: CheckoutCommand): Promise<CheckoutResult> {
    return this.withOptionalIdempotency(
      cmd.idempotencyKey,
      `checkout:${cmd.cartId}:${cmd.commitInventoryImmediately ?? true}`,
      async () => {
        return this.lockManager.withLock(`cart:${cmd.cartId}`, async () => {
          const now = this.clock();
          const cart = await this.loadCartOrThrow(cmd.cartId);

          if (cmd.expectedVersion !== undefined && cart.version !== cmd.expectedVersion) {
            throw new ConcurrencyConflictError(cmd.cartId, cmd.expectedVersion, cart.version);
          }

          if (cart.items.length === 0) {
            throw new ValidationError("Cannot checkout an empty cart");
          }

          const persistedVersion = cart.version;

          // Refresh catalog prices in batch & verify all SKUs are still active
          await this.syncCatalogPrices(cart, now, { requireAllActive: true });

          const pricing = this.pricingEngine.calculate(cart, now);
          const grandTotal = Money.ofMinor(pricing.grandTotal.amountMinor, pricing.currency);

          const stockRequest = cart.items.map((item) => ({
            sku: item.sku,
            quantity: item.quantity,
          }));

          const reservation = await this.inventory.reserve(cart.id, stockRequest);
          const orderId = `ord_${randomUUID()}`;

          try {
            cart.markCheckedOut(orderId, reservation.reservationId, grandTotal, now);
            await this.repository.save(cart.toSnapshot(), persistedVersion);
          } catch (error) {
            // Saga compensation: release reserved stock if cart save fails
            await this.inventory.releaseReservation(reservation.reservationId);
            throw error;
          }

          if (cmd.commitInventoryImmediately !== false) {
            await this.inventory.commitReservation(reservation.reservationId);
          }

          await this.publishPending(cart);

          return {
            orderId,
            reservationId: reservation.reservationId,
            cart: cart.toSnapshot(),
            pricing,
            checkedOutAt: now.toISOString(),
          };
        });
      },
    );
  }

  /**
   * Background housekeeping job: expires stale active carts and emits CartExpired events.
   */
  async purgeExpiredCarts(): Promise<number> {
    const now = this.clock();
    const expiredSnapshots = await this.repository.purgeExpired(now);
    const events: CartDomainEvent[] = expiredSnapshots.map((snapshot) => ({
      eventId: randomUUID(),
      type: "CartExpired",
      cartId: snapshot.id,
      cartVersion: snapshot.version,
      occurredAt: now.toISOString(),
      payload: { expiredAt: snapshot.expiresAt },
    }));
    if (events.length > 0) {
      await this.eventBus.publish(events);
    }
    return expiredSnapshots.length;
  }

  private async mutateCart(
    cartId: string,
    explicitExpectedVersion: number | undefined,
    mutator: (cart: Cart, now: Date) => Promise<void> | void,
  ): Promise<CartView> {
    return this.lockManager.withLock(`cart:${cartId}`, async () => {
      const maxAttempts = explicitExpectedVersion !== undefined ? 1 : this.maxOptimisticRetries;

      for (let attempt = 1; attempt <= maxAttempts; attempt++) {
        const now = this.clock();
        const cart = await this.loadCartOrThrow(cartId);
        const loadedVersion = cart.version;

        if (explicitExpectedVersion !== undefined && loadedVersion !== explicitExpectedVersion) {
          throw new ConcurrencyConflictError(cartId, explicitExpectedVersion, loadedVersion);
        }

        await mutator(cart, now);

        // Skip repository write if nothing mutated the aggregate
        if (cart.version === loadedVersion) {
          return this.buildView(cart, now);
        }

        try {
          await this.repository.save(cart.toSnapshot(), loadedVersion);
          await this.publishPending(cart);
          return this.buildView(cart, now);
        } catch (error) {
          if (error instanceof ConcurrencyConflictError && attempt < maxAttempts) {
            continue;
          }
          throw error;
        }
      }

      throw new ConcurrencyConflictError(cartId, -1, -1);
    });
  }

  private async syncCatalogPrices(
    cart: Cart,
    now: Date,
    options: { requireAllActive?: boolean } = {},
  ): Promise<void> {
    const skus = cart.items.map((i) => i.sku);
    if (skus.length === 0) return;

    const products = await this.catalog.getProducts(skus);
    for (const sku of skus) {
      const product = products.get(sku);
      if (!product) {
        if (options.requireAllActive) {
          throw new ProductNotFoundError(sku);
        }
        continue;
      }
      cart.refreshItemPrice(
        sku,
        {
          name: product.name,
          category: product.category,
          unitPrice: product.price,
          taxExempt: product.taxExempt,
        },
        now,
      );
    }
  }

  private async loadCartOrThrow(cartId: string): Promise<Cart> {
    const snapshot = await this.repository.findById(cartId);
    if (!snapshot) {
      throw new CartNotFoundError(cartId);
    }
    return Cart.fromSnapshot(snapshot, this.limits);
  }

  private buildView(cart: Cart, now: Date): CartView {
    return {
      cart: cart.toSnapshot(),
      pricing: this.pricingEngine.calculate(cart, now),
    };
  }

  private async publishPending(cart: Cart): Promise<void> {
    const events = cart.pullEvents();
    if (events.length > 0) {
      await this.eventBus.publish(events);
    }
  }

  private async withOptionalIdempotency<T>(
    key: string | undefined,
    fingerprint: string,
    operation: () => Promise<T>,
  ): Promise<T> {
    if (!key || !key.trim()) {
      return operation();
    }
    const { result } = await this.idempotencyStore.execute(
      key.trim(),
      fingerprint,
      this.idempotencyTtlMs,
      operation,
    );
    return result;
  }
}

import { createServer, type IncomingMessage, type Server, type ServerResponse } from "node:http";
import type { CartService, CartView } from "../application/cart-service.ts";
import { DomainError, ValidationError, type DomainErrorCode } from "../domain/errors.ts";

const MAX_BODY_BYTES = 256 * 1024; // 256 KB

const ERROR_STATUS_MAP: Record<DomainErrorCode, number> = {
  VALIDATION_ERROR: 400,
  CART_NOT_FOUND: 404,
  PRODUCT_NOT_FOUND: 404,
  CONCURRENCY_CONFLICT: 409,
  INSUFFICIENT_STOCK: 409,
  INVALID_CART_STATE: 409,
  IDEMPOTENCY_CONFLICT: 409,
  CART_LIMIT_EXCEEDED: 422,
  CURRENCY_MISMATCH: 422,
  INVALID_COUPON: 422,
  LOCK_TIMEOUT: 503,
};

function sendJson(
  res: ServerResponse,
  statusCode: number,
  body: unknown,
  extraHeaders: Record<string, string> = {},
): void {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    "content-type": "application/json; charset=utf-8",
    "content-length": String(Buffer.from(payload, "utf-8").length),
    ...extraHeaders,
  });
  res.end(payload);
}

function sendCartView(res: ServerResponse, statusCode: number, view: CartView): void {
  sendJson(res, statusCode, view, {
    etag: `"v${view.cart.version}"`,
  });
}

function getHeader(req: IncomingMessage, name: string): string | undefined {
  const value = req.headers[name.toLowerCase()];
  if (Array.isArray(value)) return value[0];
  return value;
}

function parseIfMatchVersion(req: IncomingMessage): number | undefined {
  const raw = getHeader(req, "if-match")?.trim();
  if (!raw) return undefined;
  const cleaned = raw.replace(/^W\//i, "").replace(/^"|"$/g, "").replace(/^v/i, "");
  const parsed = Number(cleaned);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    throw new ValidationError(`Invalid If-Match version header: "${raw}"`);
  }
  return parsed;
}

async function readJsonBody(req: IncomingMessage): Promise<Record<string, unknown>> {
  const chunks: Buffer[] = [];
  let totalBytes = 0;

  for await (const chunk of req) {
    totalBytes += chunk.length;
    if (totalBytes > MAX_BODY_BYTES) {
      throw new ValidationError(`Request body exceeds limit of ${MAX_BODY_BYTES} bytes`);
    }
    chunks.push(chunk);
  }

  if (totalBytes === 0) {
    return {};
  }

  const raw = Buffer.concat(chunks).toString("utf-8").trim();
  if (!raw) return {};

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new ValidationError("Request body must be valid JSON");
  }

  if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
    throw new ValidationError("Request body must be a JSON object");
  }
  return parsed as Record<string, unknown>;
}

function requireString(obj: Record<string, unknown>, field: string): string {
  const value = obj[field];
  if (typeof value !== "string" || !value.trim()) {
    throw new ValidationError(`Field "${field}" must be a non-empty string`);
  }
  return value.trim();
}

function requireNumber(obj: Record<string, unknown>, field: string): number {
  const value = obj[field];
  if (typeof value !== "number" || !Number.isFinite(value)) {
    throw new ValidationError(`Field "${field}" must be a finite number`);
  }
  return value;
}

function optionalString(obj: Record<string, unknown>, field: string): string | undefined {
  const value = obj[field];
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "string") {
    throw new ValidationError(`Field "${field}" must be a string`);
  }
  return value;
}

function optionalStringRecord(
  obj: Record<string, unknown>,
  field: string,
): Record<string, string> | undefined {
  const value = obj[field];
  if (value === undefined || value === null) return undefined;
  if (typeof value !== "object" || Array.isArray(value)) {
    throw new ValidationError(`Field "${field}" must be a key-value object of strings`);
  }
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (typeof v !== "string") {
      throw new ValidationError(`Field "${field}.${k}" must be a string`);
    }
    out[k] = v;
  }
  return out;
}

export function createCartHttpServer(cartService: CartService): Server {
  return createServer(async (req, res) => {
    try {
      const method = (req.method ?? "GET").toUpperCase();
      const url = new URL(req.url ?? "/", "http://localhost");
      const segments = url.pathname
        .split("/")
        .filter(Boolean)
        .map((s) => decodeURIComponent(s));

      const idempotencyKey = getHeader(req, "idempotency-key");
      const expectedVersion = parseIfMatchVersion(req);

      // GET /health
      if (method === "GET" && segments.length === 1 && segments[0] === "health") {
        sendJson(res, 200, { status: "ok", timestamp: new Date().toISOString() });
        return;
      }

      // POST /carts
      if (method === "POST" && segments.length === 1 && segments[0] === "carts") {
        const body = await readJsonBody(req);
        const view = await cartService.createCart({
          ownerId: optionalString(body, "ownerId") ?? null,
          currency: optionalString(body, "currency"),
          shippingRegion: optionalString(body, "shippingRegion"),
          metadata: optionalStringRecord(body, "metadata"),
          idempotencyKey,
        });
        sendCartView(res, 201, view);
        return;
      }

      // Routes starting with /carts/:cartId
      if (segments[0] === "carts" && segments[1]) {
        const cartId = segments[1];

        // GET /carts/:cartId
        if (method === "GET" && segments.length === 2) {
          const refreshPrices = url.searchParams.get("refreshPrices") === "true";
          const view = await cartService.getCart(cartId, { refreshPrices });
          sendCartView(res, 200, view);
          return;
        }

        // POST /carts/:cartId/items
        if (method === "POST" && segments.length === 3 && segments[2] === "items") {
          const body = await readJsonBody(req);
          const view = await cartService.addItem({
            cartId,
            sku: requireString(body, "sku"),
            quantity: requireNumber(body, "quantity"),
            metadata: optionalStringRecord(body, "metadata"),
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // DELETE /carts/:cartId/items (clear cart)
        if (method === "DELETE" && segments.length === 3 && segments[2] === "items") {
          const view = await cartService.clearCart(cartId, {
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // PATCH /carts/:cartId/items/:sku
        if (method === "PATCH" && segments.length === 4 && segments[2] === "items" && segments[3]) {
          const body = await readJsonBody(req);
          const view = await cartService.updateItemQuantity({
            cartId,
            sku: segments[3],
            quantity: requireNumber(body, "quantity"),
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // DELETE /carts/:cartId/items/:sku
        if (method === "DELETE" && segments.length === 4 && segments[2] === "items" && segments[3]) {
          const view = await cartService.removeItem({
            cartId,
            sku: segments[3],
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // POST /carts/:cartId/coupons
        if (method === "POST" && segments.length === 3 && segments[2] === "coupons") {
          const body = await readJsonBody(req);
          const view = await cartService.applyCoupon({
            cartId,
            code: requireString(body, "code"),
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // DELETE /carts/:cartId/coupons/:code
        if (method === "DELETE" && segments.length === 4 && segments[2] === "coupons" && segments[3]) {
          const view = await cartService.removeCoupon({
            cartId,
            code: segments[3],
            idempotencyKey,
            expectedVersion,
          });
          sendCartView(res, 200, view);
          return;
        }

        // PATCH /carts/:cartId/shipping-region
        if (method === "PATCH" && segments.length === 3 && segments[2] === "shipping-region") {
          const body = await readJsonBody(req);
          const view = await cartService.setShippingRegion(
            cartId,
            requireString(body, "shippingRegion"),
            { expectedVersion },
          );
          sendCartView(res, 200, view);
          return;
        }

        // POST /carts/:cartId/merge
        if (method === "POST" && segments.length === 3 && segments[2] === "merge") {
          const body = await readJsonBody(req);
          const view = await cartService.mergeCarts({
            sourceCartId: requireString(body, "sourceCartId"),
            targetCartId: cartId,
            idempotencyKey,
          });
          sendCartView(res, 200, view);
          return;
        }

        // POST /carts/:cartId/checkout
        if (method === "POST" && segments.length === 3 && segments[2] === "checkout") {
          const body = await readJsonBody(req);
          const commitInventoryImmediately =
            typeof body["commitInventoryImmediately"] === "boolean"
              ? body["commitInventoryImmediately"]
              : true;
          const result = await cartService.checkout({
            cartId,
            commitInventoryImmediately,
            idempotencyKey,
            expectedVersion,
          });
          sendJson(res, 200, result, {
            etag: `"v${result.cart.version}"`,
          });
          return;
        }
      }

      sendJson(res, 404, {
        error: {
          code: "ROUTE_NOT_FOUND",
          message: `No route matches ${method} ${url.pathname}`,
        },
      });
    } catch (error) {
      if (error instanceof DomainError) {
        const status = ERROR_STATUS_MAP[error.code] ?? 400;
        sendJson(res, status, {
          error: {
            code: error.code,
            message: error.message,
            details: error.details,
          },
        });
        return;
      }

      sendJson(res, 500, {
        error: {
          code: "INTERNAL_ERROR",
          message: error instanceof Error ? error.message : "Unexpected server error",
        },
      });
    }
  });
}

